"""The handover (#29): generated by `end` from a fixture ledger, committed beside it, and
drawn over the shift status comment; asserted through the command line (ADR 0007)."""
import json
from pathlib import Path

from tests.test_mirror import Board, board
from tests.test_shift import LEDGER, REPO, SLUG, issue
from tests.test_tickets import BRANCH, Armed

FIXTURE = Path(__file__).parent / "fixtures" / "handover-ledger.json"  # synthetic, no session data
HANDOVER = LEDGER.with_suffix(".handover.md")
SECTIONS = ["#### Needs you", "#### Done", "#### Security findings", "#### ADR candidates",
            "#### Refused actions", "#### Sub-issues added after the prescan",
            "<details><summary>Nits and per-ticket usage</summary>"]


class Handover(Board, Armed):
    """An armed shift on a laid-out board; each test swaps in the fixture ledger and ends."""

    def prepare(self):
        self.found(board(), Issues={"repository": {f"i{n}": {"id": f"N{n}"} for n in range(21, 29)}},
                   AddCards={f"c{n}": {"item": {"id": f"I{n}"}} for n in range(21, 29)})
        self.assertEqual(self.setup_board()[0], 0)
        super().prepare()
        self.clear()

    def end(self, *flags, ledger=None, added=True):
        (self.target / LEDGER).write_text(json.dumps(ledger or json.loads(FIXTURE.read_text())))
        self.git("commit", "-qam", "ledger: fixture")
        self.git("push", "-q", "origin", BRANCH)
        api = json.loads((self.gh / "fixture.json").read_text())["api"]
        path = f"repos/{REPO}/issues/20/sub_issues"
        if added:  # #29 joined the spec after the prescan
            api[path] = [issue(n) for n in range(21, 29)] + [{**issue(29), "title": "Added later"}]
        else:
            api.pop(path)
        self.canned(api=api)
        return self.shift("end", "--gen", "1", "--reason", "frontier empty", *flags)

    def file(self, name, text):
        (self.tmp / name).write_text(text)
        return str(self.tmp / name)

    def test_the_handover_from_a_fixture_ledger(self):
        top = self.git("rev-parse", "--show-toplevel")
        main = self.git("rev-parse", "main", cwd=self.remote)
        code, out = self.end(
            "--findings", self.file("findings.md", f"- low: debug log in {top}/src/app.py "
                                                   f"prints ghp_{'a' * 30}"),
            "--candidates", self.file("candidates.md", "- Prices as integer cents"))
        self.assertEqual(code, 0, out)
        text = (self.target / HANDOVER).read_text()
        lines = text.splitlines()
        self.assertEqual(lines[0], "### 2/8 done · 4 need you · 1 refused · 17 points")  # Stalled too
        positions = [text.index(s) for s in SECTIONS]
        self.assertEqual(positions, sorted(positions))  # the spec's order
        needs = text[positions[0]:positions[1]]
        self.assertIn("- **#22 Second** · blocker: Is a missing price an error or zero?\n"
                      "  - waiting on it: #27, #28", needs)
        self.assertIn("- **#23 Human** · human work\n  - waiting on it: nothing", needs)
        self.assertIn("- **#26 Fifth** · stalled: 3 blocked stops in a row", needs)
        self.assertIn("- Not reached: #27 Third (Backlog), #28 Fourth (Backlog)", needs)
        # human-verified: left open in Needs you, with the steps to run
        self.assertIn("- **#25 Triage** · needs your run; close the issue after it:\n"
                      "  - [ ] It looks right · [steps](https://github.com/acme/widget/blob/"
                      f"{'a1' * 20}/verify/evidence/25-recipe.md)", needs)
        self.assertNotIn(f"repos/{REPO}/issues/25", self.ops())  # never closed
        self.assertIn("- #21 First · 2 criteria met · evidence [1](https://github.com/acme/widget/"
                      f"blob/{'a1' * 20}/verify/evidence/21-runs.txt) [2](", text)
        self.assertIn("- #24 Old · closed before the shift", text)
        self.assertIn("- low: debug log in ./src/app.py prints [redacted]", text)
        self.assertIn("(the model's view, not a decision)\n- Prices as integer cents", text)
        self.assertIn("1 refused.\n- 2026-11-20T02:00:00+00:00 · guard · #22 · `git push origin main`",
                      text)
        self.assertIn("after the prescan\n- #29 Added later", text)
        folded = text[positions[-1]:]
        self.assertIn("- #21: a newline in a criterion breaks the table", folded)
        self.assertIn("| #21 | 10 |\n| #22 | 3 |\n| #25 | 4 |", folded)
        self.assertNotIn("prices are integers in cents", text)  # decisions are not nits
        self.assertEqual(lines[-1], "Rerun all verification, model-free: `verify/checks`")
        # committed beside the ledger, pushed, and drawn over the shift status comment
        self.assert_ledger_commit("ledger: #20 ended")
        self.assertIn(str(HANDOVER), self.git("show", "--name-only", "--format=", "HEAD"))
        self.assertEqual(self.git("show", f"{BRANCH}:{HANDOVER}", cwd=self.remote), text.strip())
        comment = self.comment()
        self.assertEqual(comment, f"<!-- third-shift status {SLUG} {'b2' * 20} -->\n{text}")
        self.assertNotIn(str(Path(top).parent), "\n".join(self.writes()))
        self.assertNotIn(str(Path(top).parent), text)
        self.assertEqual(self.git("rev-parse", "main", cwd=self.remote), main)  # end state: branch

    def comment(self):
        return self.bodies(f"repos/{REPO}/issues/comments/501")[-1]

    def test_zero_refused_still_shows_and_missing_records_say_so(self):
        ledger = json.loads(FIXTURE.read_text())
        ledger.pop("refused")
        code, out = self.end(ledger=ledger, added=False)
        self.assertEqual(code, 0, out)
        text = (self.target / HANDOVER).read_text()
        self.assertIn(" · 0 refused · ", text.splitlines()[0])
        self.assertIn("#### Refused actions\n0 refused.\n", text)
        self.assertIn("#### Security findings (security-preflight)\nNone.\n", text)
        self.assertIn("Unknown: the tracker could not be read", text)

    def test_end_refuses_an_unreadable_findings_file_and_writes_nothing(self):
        ledger = json.loads(FIXTURE.read_text())
        (self.target / LEDGER).write_text(json.dumps(ledger))
        self.git("commit", "-qam", "ledger: fixture")
        self.git("push", "-q", "origin", BRANCH)
        before = self.snapshot()
        code, out = self.shift("end", "--gen", "1", "--reason", "x", "--findings",
                               str(self.tmp / "missing.md"))
        self.assertEqual(code, 1, out)
        self.assertEqual(self.snapshot(), before)
        self.assertFalse((self.target / HANDOVER).exists())

    def test_refusals_off_the_ledger_are_counted_and_listed(self):
        self.git("checkout", "-q", "-b", "elsewhere")  # #27's fallback: off the shift branch
        hook = {"session_id": "s1", "cwd": str(self.target), "hook_event_name": "PreToolUse",
                "tool_name": "Bash", "tool_input": {"command": "git push origin main"}}
        self.assertEqual(self.shift("guard", input=json.dumps(hook))[0], 0)
        self.git("checkout", "-q", BRANCH)
        self.assertEqual(self.shift("wait", "--gen", "7")[0], 2)  # a stale lease
        code, out = self.end()
        self.assertEqual(code, 0, out)
        text = (self.target / HANDOVER).read_text()
        self.assertIn(" · 3 refused · ", text.splitlines()[0])
        self.assertIn("#### Refused actions\n3 refused.\n- 2026-11-20T02:00:00+00:00 · guard · ", text)
        self.assertRegex(text, r"\n- \S+ · guard · `git push origin main` · ")
        self.assertRegex(text, r"\n- \S+ · stale lease · `wait --gen 7` · the lease was at generation 1")
        off = json.loads((self.target / LEDGER).read_text())["end"]["refused_off_ledger"]
        self.assertEqual([r.get("by") or r.get("command") for r in off], ["guard", "wait"])

    def test_free_text_cannot_break_the_sections_or_a_table(self):
        ledger = json.loads(FIXTURE.read_text())
        ledger["tickets"]["22"]["why"] = "zero?\n#### Done\n- fake"
        ledger["tickets"]["25"]["verdicts"][1]["criterion"] = "It looks\n#### Done"
        ledger["notes"][0]["text"] = "a nit\n#### Done"
        top = self.git("rev-parse", "--show-toplevel")
        ledger["tickets"]["23"]["why"] = f"see {top}/src/app.py"  # cleaned as the comment is
        code, out = self.end(ledger=ledger)
        self.assertEqual(code, 0, out)
        text = (self.target / HANDOVER).read_text()
        self.assertEqual([l for l in text.splitlines() if l.startswith("#")][1:3],
                         ["#### Needs you", "#### Done"])
        self.assertEqual(text.count("\n#### Done"), 1, text)
        self.assertIn("blocker: zero? #### Done - fake", text)
        self.assertIn("- [ ] It looks #### Done · [steps]", text)
        self.assertIn("- #21: a nit #### Done", text)
        self.assertIn("human work: see ./src/app.py", text)
        self.assertNotIn(top, text)

    def test_an_empty_findings_file_reads_like_none(self):
        code, out = self.end("--findings", self.file("findings.md", "\n"), added=False)
        self.assertEqual(code, 0, out)
        self.assertIn("#### Security findings (security-preflight)\nNone.\n",
                      (self.target / HANDOVER).read_text())

    def test_a_later_shift_does_not_inherit_earlier_refusals(self):
        self.assertEqual(self.shift("wait", "--gen", "7")[0], 2)  # shift 1: a stale lease
        self.assertEqual(self.end()[0], 0)
        log = self.home / "acme" / "widget" / "refusals.jsonl"
        before = log.read_text()
        self.git("checkout", "-q", "main")
        self.prescan["spec"] = {"number": 30, "title": "Another"}
        hook = self.remote / "hooks" / "pre-receive"
        hook.write_text("#!/bin/sh\nexit 1\n")
        hook.chmod(0o755)
        self.assertEqual(self.arm()[0], 1)  # a failed arm leaves the log alone
        self.assertEqual(log.read_text(), before)
        hook.unlink()
        self.assertEqual(self.arm()[0], 0)
        self.assertFalse(log.exists())
        kept = list(log.parent.glob("refusals.*.jsonl"))  # nothing is lost
        self.assertEqual([f.read_text() for f in kept], [before])
        code, out = self.shift("end", "--gen", "1", "--reason", "frontier empty")
        self.assertEqual(code, 0, out)
        text = (self.target / "docs/third-shift-ledger/30-another.handover.md").read_text()
        self.assertIn(" · 0 refused · ", text.splitlines()[0])
        self.assertNotIn("wait --gen 7", text)

    def test_a_reason_cannot_break_the_sections(self):
        code, out = self.end("--reason", "done\n#### Done")  # the last --reason wins
        self.assertEqual(code, 0, out)
        text = (self.target / HANDOVER).read_text()
        self.assertEqual(text.count("\n#### Done"), 1, text)
        self.assertIn(" · ended: done #### Done · ", text)
